import{_ as e,c as a,o,ae as i}from"./chunks/framework.Cd-3tpCq.js";const p=JSON.parse('{"title":"Attributes","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/catalog/attributes/index.md","filePath":"api/graphql-api/admin/catalog/attributes/index.md"}'),d={name:"api/graphql-api/admin/catalog/attributes/index.md"};function r(s,t,c,n,l,u){return o(),a("div",null,t[0]||(t[0]=[i('<h1 id="attributes" tabindex="-1">Attributes <a class="header-anchor" href="#attributes" aria-label="Permalink to &quot;Attributes&quot;">​</a></h1><p>Attributes are the fields a product can carry — <code>name</code>, <code>price</code>, <code>color</code>, <code>material</code>, and so on. The Attributes menu lists, creates, edits, and deletes them, and manages the selectable options of dropdown-style attributes. It mirrors the admin <strong>Catalog → Attributes</strong> screen.</p><h2 id="attribute-types" tabindex="-1">Attribute types <a class="header-anchor" href="#attribute-types" aria-label="Permalink to &quot;Attribute types&quot;">​</a></h2><p>The <code>type</code> (fixed at creation) decides how the field is captured and stored:</p><table tabindex="0"><thead><tr><th>Type</th><th>Notes</th></tr></thead><tbody><tr><td><code>text</code> / <code>textarea</code></td><td>Free text / multi-line text.</td></tr><tr><td><code>price</code> / <code>boolean</code></td><td>A decimal price / a yes-no flag.</td></tr><tr><td><code>date</code> / <code>datetime</code></td><td>A date / a date-and-time.</td></tr><tr><td><code>image</code> / <code>file</code></td><td>An uploaded image / file.</td></tr><tr><td><code>select</code> / <code>multiselect</code> / <code>checkbox</code></td><td>A pick-list — these have <strong>options</strong> (see below).</td></tr></tbody></table><h2 id="options-for-select-multiselect-checkbox" tabindex="-1">Options (for select / multiselect / checkbox) <a class="header-anchor" href="#options-for-select-multiselect-checkbox" aria-label="Permalink to &quot;Options (for select / multiselect / checkbox)&quot;">​</a></h2><p>Only <code>select</code>, <code>multiselect</code>, and <code>checkbox</code> attributes have options (e.g. a <code>color</code> attribute&#39;s Red / Green / Blue). Options are managed through their own mutations under the attribute, and each option carries its own per-locale translations. A <code>select</code> attribute can also drive <strong>swatches</strong> (<code>swatchType</code> = dropdown / color / image) used on the storefront.</p><h2 id="configurable-filterable-system" tabindex="-1">Configurable, filterable, system <a class="header-anchor" href="#configurable-filterable-system" aria-label="Permalink to &quot;Configurable, filterable, system&quot;">​</a></h2><ul><li><strong><code>isConfigurable</code></strong> — whether the attribute can be used as a variant-defining attribute for configurable products (e.g. colour × size). Only <code>select</code>-type attributes qualify.</li><li><strong><code>isFilterable</code></strong> — whether it appears in storefront layered navigation.</li><li><strong><code>isRequired</code> / <code>isUnique</code></strong> — validation on the product form.</li><li><strong><code>valuePerLocale</code> / <code>valuePerChannel</code></strong> — whether the value can differ per locale / per channel.</li><li><strong>System attributes</strong> (<code>isUserDefined = false</code>) are the built-in fields (sku, name, price, …). Their <code>code</code> and <code>type</code> are immutable and they cannot be deleted.</li></ul><h2 id="nested-data-is-returned-whole" tabindex="-1">Nested data is returned whole <a class="header-anchor" href="#nested-data-is-returned-whole" aria-label="Permalink to &quot;Nested data is returned whole&quot;">​</a></h2><p>On the single-attribute query, <code>translations</code> and <code>options</code> (with their nested <code>translations</code>) are returned as <strong>whole JSON</strong> — query each as a bare field (<code>options</code>, not <code>options { … }</code>); the entire array comes back, and it resolves over GraphQL.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/catalog/attributes/attributes-listing.html">List attributes</a></td><td><code>adminAttributes</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/attributes/attributes-detail.html">Attribute detail</a></td><td><code>adminAttribute(id:)</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/attributes/attributes-create.html">Create attribute</a></td><td><code>createAdminAttribute</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/attributes/attributes-update.html">Update attribute</a></td><td><code>updateAdminAttribute</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/attributes/attributes-delete.html">Delete attribute</a></td><td><code>deleteAdminAttribute</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/attributes/attributes-mass-delete.html">Mass delete</a></td><td><code>createAdminAttributeMassDelete</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/catalog/attributes/attribute-options.html">Attribute options (CRUD)</a></td><td><code>createAdminAttributeOption</code> / <code>updateAdminAttributeOption</code> / <code>deleteAdminAttributeOption</code> mutations</td></tr></tbody></table><p>The single-attribute query embeds the full <code>translations</code> and <code>options</code> (with their translations) inline; the listing leaves those two heavy blocks out (fetch them by id).</p><p>All Attributes operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>. Reads require <code>catalog.attributes.view</code>; writes require the matching <code>catalog.attributes.create</code> / <code>.edit</code> / <code>.delete</code> permission.</p>',15)]))}const b=e(d,[["render",r]]);export{p as __pageData,b as default};
